import { DEFAULT_LOGO_COLORS } from "./palette";

// Grabient wordmark ported from the current site (GrabientLogo.tsx):
// currentColor lettering + gradient underline rect. The resting gradient is
// the site's default palette (palette.ts DEFAULT_PALETTE); the old brand
// stops remain only as a fallback if that seed ever fails to render.
const BRAND_STOPS = ["#ffd25f", "#ff5f6d", "#a17fff"];
export const logoStops = (colors: readonly string[]): string =>
  colors
    .map(
      (c, idx) =>
        `<stop offset="${colors.length > 1 ? ((idx / (colors.length - 1)) * 100).toFixed(1) : 0}%" stop-color="${c}"/>`,
    )
    .join("");
